def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([7]), fmt([-5]), fmt([3, 3]), fmt([1, 2]), fmt([2, 1]), fmt([5, 5, 5, 5]),
             fmt([6, 2, 9, 3, 4]), fmt([1, 3, 2, 4, 2, 5]), fmt([-3, -1, -2, 0, -4])]
    for n in (3, 5, 8, 12, 20, 30):
        for _ in range(2):
            hi = rng.choice([3, 10, 100])
            tests.append(fmt([rng.randint(-hi, hi) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt(list(range(1, N + 1))))
    tests.append(fmt(list(range(10**9, 10**9 - N, -1))))
    tests.append(fmt([rng.randint(1, 5) for _ in range(N)]))
    tests.append(fmt([(i % 1000) * 1000 + rng.randint(0, 5) for i in range(N)]))
    return tests

